{{cloze:Text}}
<br>{{Extra}}

{{#Source}}
<br><br>
<a href="{{Source}}" class="source-link" title="Source">
<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-origami-icon lucide-origami"><path d="M12 12V4a1 1 0 0 1 1-1h6.297a1 1 0 0 1 .651 1.759l-4.696 4.025"/><path d="m12 21-7.414-7.414A2 2 0 0 1 4 12.172V6.415a1.002 1.002 0 0 1 1.707-.707L20 20.009"/><path d="m12.214 3.381 8.414 14.966a1 1 0 0 1-.167 1.199l-1.168 1.163a1 1 0 0 1-.706.291H6.351a1 1 0 0 1-.625-.219L3.25 18.8a1 1 0 0 1 .631-1.781l4.165.027"/></svg>
</a>
<script>
    (function() {
        var link = document.querySelector('.source-link');
        if (link) {
            var href = link.getAttribute('href');
            if (href) {
                var match = href.match(/[?&]file=([^&]+)/);
                if (match) {
                    var file = decodeURIComponent(match[1]);
                    if (file.endsWith('.md')) {
                        file = file.substring(0, file.length - 3);
                    }
                    var noteName = file.split('/').pop();
                    link.setAttribute('title', noteName);
                }
            }
        }
    })();
</script>
{{/Source}}
{{tts it_IT speed=1.2:Text}}

1780434141774.css:
body {
    background-color: #000000;
    margin: 0;
    padding: 20px;
    display: flex;
    justify-content: center;
    align-items: center;
}
.card {
    background-color: #000000;
    color: #ffffff;
    font-family: 'Helvetica Neue', Helvetica, Arial, sans-serif;
    font-size: 22px;
    text-align: center;
    line-height: 1.6;
    border: 1px solid #ffffff;
    border-radius: 15px;
    padding: 30px;
    width: 80%;
    max-width: 600px;
    margin: auto;
    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.8), 0 0 20px rgba(255, 255, 255, 0.15);
}
.source-link {
    color: #a0a0a0;
    text-decoration: none;
    display: inline-flex;
    align-items: center;
    transition: color 0.35s, transform 0.35s;
}
.source-link:hover {
    color: #3b82f6;
    transform: scale(1.05);
}
b, strong {
    color: #FF005E;
    text-shadow: 0 0 8px rgba(255, 0, 94, 0.6), 0 0 15px rgba(255, 0, 94, 0.4);
}
i, em {
    color: #5EFF00;
    text-shadow: 0 0 8px rgba(94, 255, 0, 0.6), 0 0 15px rgba(94, 255, 0, 0.4);
}
b i, strong em, i b, em strong {
    color: #005EFF;
    text-shadow: 0 0 8px rgba(0, 94, 255, 0.6), 0 0 20px rgba(0, 94, 255, 0.5);
}

